package com.levelinghelper;

import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.HintArrowType;
import net.runelite.api.NPC;
import net.runelite.api.coords.WorldPoint;

/** Cooperates with server and other plugin arrows instead of claiming the shared arrow every tick. */
final class HintArrowController
{
	private final Client client;
	private NPC npc;
	private WorldPoint point;

	@Inject
	HintArrowController(Client client)
	{
		this.client = client;
	}

	void update(boolean enabled, NPC targetNpc, WorldPoint targetPoint)
	{
		if (!enabled || client.getGameState() != GameState.LOGGED_IN)
		{
			clear();
			return;
		}
		if (client.hasHintArrow() && !ownsCurrent())
		{
			npc = null;
			point = null;
			return;
		}
		if (targetNpc != null)
		{
			if (npc != targetNpc || !ownsCurrent())
			{
				client.setHintArrow(targetNpc);
			}
			npc = targetNpc;
			point = null;
		}
		else if (targetPoint != null)
		{
			if (!targetPoint.equals(point) || !ownsCurrent())
			{
				client.setHintArrow(targetPoint);
			}
			point = targetPoint;
			npc = null;
		}
		else
		{
			clear();
		}
	}

	void clear()
	{
		if (ownsCurrent())
		{
			client.clearHintArrow();
		}
		npc = null;
		point = null;
	}

	private boolean ownsCurrent()
	{
		return npc != null && client.getHintArrowType() == HintArrowType.NPC && client.getHintArrowNpc() == npc
			|| point != null && client.getHintArrowType() == HintArrowType.COORDINATE && point.equals(client.getHintArrowPoint());
	}
}

package com.levelinghelper;

import com.levelinghelper.model.AccountMode;
import com.levelinghelper.model.TrainingStyle;
import java.awt.Color;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;

@ConfigGroup(LevelingHelperConfig.GROUP)
public interface LevelingHelperConfig extends Config
{
	String GROUP = "levelinghelper";

	@ConfigItem(
		keyName = "showOverlay",
		name = "Show guide box",
		description = "Show the current step, distance, and XP rates on the game view.",
		position = 1
	)
	default boolean showOverlay()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showTiles",
		name = "Mark the destination",
		description = "Highlight the tile you are walking to.",
		position = 2
	)
	default boolean showTiles()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showObjects",
		name = "Highlight targets",
		description = "Highlight the NPCs and objects for the current step.",
		position = 3
	)
	default boolean showObjects()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showArrow",
		name = "Direction arrow",
		description = "Point toward the destination when it is off screen.",
		position = 4
	)
	default boolean showArrow()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showHintArrow",
		name = "Native hint arrow",
		description = "Also use the game's shared yellow arrow when no other plugin or server arrow is active.",
		position = 9
	)
	default boolean showHintArrow()
	{
		return false;
	}

	@ConfigItem(
		keyName = "allowWilderness",
		name = "Include Wilderness routes",
		description = "Allow routes where other players can kill you and take your items. Disabled by default.",
		position = 10
	)
	default boolean allowWilderness()
	{
		return false;
	}

	@ConfigItem(
		keyName = "showWorldMap",
		name = "World map marker",
		description = "Mark the destination on the world map.",
		position = 5
	)
	default boolean showWorldMap()
	{
		return true;
	}

	@ConfigItem(
		keyName = "autoAdvance",
		name = "Auto-advance steps",
		description = "Move to the next step when you arrive, finish at the bank, or fill your inventory.",
		position = 6
	)
	default boolean autoAdvance()
	{
		return true;
	}

	@Range(min = 3, max = 40)
	@ConfigItem(
		keyName = "arrivalDistance",
		name = "Arrival distance",
		description = "Maximum distance in tiles that counts as arriving. Routes may require a tighter radius.",
		position = 7
	)
	default int arrivalDistance()
	{
		return 10;
	}

	@ConfigItem(
		keyName = "highlightColor",
		name = "Highlight color",
		description = "Color used for the destination and the targets.",
		position = 8
	)
	default Color highlightColor()
	{
		return new Color(80, 210, 140);
	}

	@ConfigItem(
		keyName = "accountMode",
		name = "Account mode",
		description = "Saved free-to-play or members choice.",
		hidden = true
	)
	default AccountMode accountMode()
	{
		return AccountMode.F2P;
	}

	@ConfigItem(
		keyName = "trainingStyle",
		name = "Training style",
		description = "Saved training style.",
		hidden = true
	)
	default TrainingStyle trainingStyle()
	{
		return TrainingStyle.BALANCED;
	}

	@ConfigItem(
		keyName = "goalLevel",
		name = "Goal level",
		description = "Saved goal level.",
		hidden = true
	)
	default int goalLevel()
	{
		return 99;
	}

	@ConfigItem(
		keyName = "skillName",
		name = "Skill",
		description = "Saved skill.",
		hidden = true
	)
	default String skillName()
	{
		return "Woodcutting";
	}
}

package com.levelinghelper;

import com.levelinghelper.guide.DirectionArrow;
import com.levelinghelper.guide.GuideController;
import com.levelinghelper.guide.TrainingMath;
import com.levelinghelper.model.GuideStep;
import com.levelinghelper.model.TrainingMethod;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.Rectangle;
import java.awt.Shape;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.DecorativeObject;
import net.runelite.api.GameObject;
import net.runelite.api.GameState;
import net.runelite.api.GroundObject;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.api.TileObject;
import net.runelite.api.WallObject;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;

class LevelingHelperOverlay extends Overlay
{
	private final Client client;
	private final LevelingHelperPlugin plugin;
	private final LevelingHelperConfig config;

	@Inject
	LevelingHelperOverlay(Client client, LevelingHelperPlugin plugin, LevelingHelperConfig config)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		GuideController controller = plugin.controller();
		if (!plugin.active() || !controller.running() || client.getGameState() != GameState.LOGGED_IN)
		{
			return null;
		}
		GuideStep step = controller.current();
		TrainingMethod method = controller.method();
		if (step == null || method == null)
		{
			return null;
		}
		Color color = config.highlightColor();
		if (config.showTiles())
		{
			renderTile(graphics, step.target(), color);
		}
		if (config.showObjects())
		{
			renderTargets(graphics, color);
		}
		if (config.showArrow())
		{
			renderArrow(graphics, step.target(), color);
		}
		if (config.showOverlay())
		{
			renderBox(graphics, method, step, color);
		}
		return null;
	}

	private void renderTile(Graphics2D graphics, WorldPoint target, Color color)
	{
		if (target == null || target.getPlane() != client.getPlane())
		{
			return;
		}
		LocalPoint local = LocalPoint.fromWorld(client, target);
		if (local == null)
		{
			return;
		}
		Polygon polygon = net.runelite.api.Perspective.getCanvasTilePoly(client, local);
		if (polygon != null)
		{
			OverlayUtil.renderPolygon(graphics, polygon, color, new Color(color.getRed(), color.getGreen(), color.getBlue(), 40), new BasicStroke(2));
		}
	}

	private void renderTargets(Graphics2D graphics, Color color)
	{
		for (NPC npc : plugin.highlightedNpcs())
		{
			Shape hull = npc.getConvexHull();
			if (hull != null)
			{
				OverlayUtil.renderPolygon(graphics, hull, color);
			}
		}
		for (TileObject object : plugin.highlightedObjects())
		{
			Shape hull = hull(object);
			if (hull != null)
			{
				OverlayUtil.renderPolygon(graphics, hull, color);
			}
		}
	}

	private void renderArrow(Graphics2D graphics, WorldPoint target, Color color)
	{
		Player player = client.getLocalPlayer();
		if (player == null || target == null || player.getWorldLocation().getPlane() != target.getPlane())
		{
			return;
		}
		Rectangle viewport = new Rectangle(client.getViewportXOffset(), client.getViewportYOffset(),
			client.getViewportWidth(), client.getViewportHeight());
		LocalPoint local = LocalPoint.fromWorld(client, target);
		Polygon tile = local == null ? null : net.runelite.api.Perspective.getCanvasTilePoly(client, local);
		if (tile != null && tile.intersects(viewport))
		{
			return;
		}
		Polygon triangle = DirectionArrow.polygon(target.getX() - player.getWorldLocation().getX(),
			target.getY() - player.getWorldLocation().getY(), client.getCameraYaw(), viewport);
		if (triangle == null)
		{
			return;
		}
		graphics.setColor(color);
		graphics.fill(triangle);
	}

	private void renderBox(Graphics2D graphics, TrainingMethod method, GuideStep step, Color color)
	{
		Player player = client.getLocalPlayer();
		int level = player == null ? 1 : client.getRealSkillLevel(method.skill());
		String distance = step.target() == null || player == null
			? ""
			: TrainingMath.direction(player.getWorldLocation(), step.target());
		String[] lines = new String[]{
			method.skill().getName() + "  " + level + " / " + config.goalLevel(),
			method.name() + "   step " + (plugin.controller().stepIndex() + 1) + "/" + method.steps().size(),
			trim(step.instruction(), 52),
			distance.isEmpty() ? "Follow the step in the side panel" : distance,
			"Typical " + TrainingMath.rate(method.xpPerHour())
		};
		graphics.setFont(graphics.getFont().deriveFont(12f));
		int width = 230;
		for (String line : lines)
		{
			width = Math.max(width, graphics.getFontMetrics().stringWidth(line) + 16);
		}
		int height = 14 + lines.length * 15;
		graphics.setColor(new Color(12, 16, 14, 210));
		graphics.fillRoundRect(8, 8, width, height, 8, 8);
		graphics.setColor(color);
		graphics.setStroke(new BasicStroke(1.5f));
		graphics.drawRoundRect(8, 8, width, height, 8, 8);
		int y = 24;
		for (int i = 0; i < lines.length; i++)
		{
			graphics.setColor(i == 2 ? Color.WHITE : new Color(210, 225, 215));
			graphics.drawString(lines[i], 16, y);
			y += 15;
		}
	}

	private static Shape hull(TileObject object)
	{
		if (object instanceof GameObject)
		{
			return ((GameObject) object).getConvexHull();
		}
		if (object instanceof WallObject)
		{
			return ((WallObject) object).getConvexHull();
		}
		if (object instanceof GroundObject)
		{
			return ((GroundObject) object).getConvexHull();
		}
		if (object instanceof DecorativeObject)
		{
			return ((DecorativeObject) object).getConvexHull();
		}
		return null;
	}

	private static String trim(String text, int max)
	{
		if (text == null)
		{
			return "";
		}
		String flat = text.replace('\n', ' ');
		if (flat.length() <= max)
		{
			return flat;
		}
		return flat.substring(0, max - 3) + "...";
	}
}

package com.levelinghelper;

import com.levelinghelper.guide.GuideSnapshot;
import com.levelinghelper.guide.TrainingMath;
import com.levelinghelper.model.AccountMode;
import com.levelinghelper.model.GuideStep;
import com.levelinghelper.model.TrainingMethod;
import com.levelinghelper.model.TrainingStyle;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.GridLayout;
import java.awt.Insets;
import java.util.HashMap;
import java.util.Map;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.ButtonGroup;
import javax.swing.JButton;
import javax.swing.JComboBox;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JSpinner;
import javax.swing.JToggleButton;
import javax.swing.SpinnerNumberModel;
import javax.swing.plaf.basic.BasicHTML;
import javax.swing.text.View;
import net.runelite.api.Skill;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.PluginPanel;

class LevelingHelperPanel extends PluginPanel
{
	private static final Color TEXT = new Color(230, 230, 230);
	private static final Color DIM = new Color(170, 176, 170);
	private static final Color WARN = new Color(230, 150, 90);

	private final LevelingHelperPlugin plugin;
	private final JComboBox<AccountMode> mode = new JComboBox<AccountMode>(AccountMode.values());
	private final JComboBox<TrainingStyle> style = new JComboBox<TrainingStyle>(TrainingStyle.values());
	private final JSpinner goal = new JSpinner(new SpinnerNumberModel(99, 2, 99, 1));
	private final JPanel skills = new JPanel(new GridLayout(0, 2, 4, 4));
	private final JPanel detail = new JPanel();
	private final Map<Skill, JToggleButton> skillButtons = new HashMap<Skill, JToggleButton>();
	private final ButtonGroup skillGroup = new ButtonGroup();
	private boolean suppress;
	private String signature = "";
	private WrapLabel statsLabel;

	LevelingHelperPanel(LevelingHelperPlugin plugin)
	{
		super();
		this.plugin = plugin;
		if (getScrollPane() != null)
		{
			getScrollPane().getVerticalScrollBar().setUnitIncrement(18);
		}

		JPanel top = column();
		top.add(text("Leveling Helper", TEXT));
		top.add(text("Pick a skill. A yellow arrow marks the next bank, tree, or NPC.", DIM));
		top.add(Box.createVerticalStrut(6));
		top.add(labeled("Account", mode));
		top.add(labeled("Style", style));
		top.add(labeled("Goal", goal));
		JButton match = button("Match account");
		match.addActionListener(event -> plugin.detectMembership());
		top.add(match);
		top.add(Box.createVerticalStrut(6));
		styleSkills();
		top.add(skills);

		detail.setLayout(new BoxLayout(detail, BoxLayout.Y_AXIS));
		detail.setBackground(ColorScheme.DARK_GRAY_COLOR);
		detail.setAlignmentX(Component.LEFT_ALIGNMENT);
		add(top);
		add(detail);

		mode.addActionListener(event ->
		{
			if (!suppress)
			{
				plugin.setAccountMode((AccountMode) mode.getSelectedItem());
			}
		});
		style.addActionListener(event ->
		{
			if (!suppress)
			{
				plugin.setTrainingStyle((TrainingStyle) style.getSelectedItem());
			}
		});
		goal.addChangeListener(event ->
		{
			if (!suppress)
			{
				plugin.setGoal((Integer) goal.getValue());
			}
		});
	}

	void load(AccountMode accountMode, TrainingStyle trainingStyle, Skill skill, int goalLevel)
	{
		suppress = true;
		mode.setSelectedItem(accountMode);
		style.setSelectedItem(trainingStyle);
		goal.setValue(goalLevel);
		JToggleButton button = skillButtons.get(skill);
		if (button != null)
		{
			button.setSelected(true);
		}
		suppress = false;
	}

	void apply(GuideSnapshot snapshot)
	{
		load(snapshot.mode(), snapshot.style(), snapshot.skill(), snapshot.goal());
		String next = snapshot.skill().name()
			+ snapshot.mode()
			+ snapshot.style()
			+ snapshot.goal()
			+ snapshot.running()
			+ snapshot.loggedIn()
			+ snapshot.atGoal()
			+ snapshot.status()
			+ (snapshot.method() == null ? "" : snapshot.method().id())
			+ snapshot.stepIndex()
			+ snapshot.alternatives().toString()
			+ snapshot.preparation()
			+ snapshot.lockedRoutes();
		if (!next.equals(signature) || statsLabel == null)
		{
			signature = next;
			rebuild(snapshot);
		}
		else
		{
			statsLabel.setText(html(stats(snapshot)));
			statsLabel.invalidate();
		}
	}

	private void rebuild(GuideSnapshot snapshot)
	{
		detail.removeAll();
		detail.add(text(snapshot.status(), snapshot.status().startsWith("You are on a free") || snapshot.status().contains("members skill") ? WARN : DIM));
		detail.add(controls(snapshot));
		detail.add(Box.createVerticalStrut(6));
		if (snapshot.method() == null)
		{
			appendLockedRoutes(snapshot);
			statsLabel = null;
			refresh();
			return;
		}
		TrainingMethod method = snapshot.method();
		detail.add(text(method.name(), new Color(120, 220, 150)));
		if (!method.steps().isEmpty())
		{
			int stepIndex = snapshot.running()
				? Math.min(snapshot.stepIndex(), method.steps().size() - 1)
				: 0;
			GuideStep currentStep = method.steps().get(stepIndex);
			String heading = currentStep.instruction();
			detail.add(text(heading, new Color(255, 214, 120)));
		}
		detail.add(text(method.summary(), TEXT));
		if (!snapshot.preparation().isEmpty())
		{
			detail.add(text("Before training", TEXT));
			for (String requirement : snapshot.preparation())
			{
				detail.add(text(requirement, WARN));
			}
		}
		statsLabel = text(stats(snapshot), DIM);
		detail.add(statsLabel);
		detail.add(text(method.rateNote(), DIM));
		if (snapshot.upcoming() != null)
		{
			detail.add(text("Next unlock at " + (method.maxLevel() + 1) + ": " + snapshot.upcoming().name(), DIM));
		}
		if (snapshot.alternatives().size() > 1)
		{
			JComboBox<TrainingMethod> others = new JComboBox<TrainingMethod>();
			for (TrainingMethod alternative : snapshot.alternatives())
			{
				others.addItem(alternative);
			}
			others.setSelectedItem(method);
			others.setAlignmentX(Component.LEFT_ALIGNMENT);
			others.setMaximumSize(new Dimension(Integer.MAX_VALUE, 28));
			others.addActionListener(event ->
			{
				TrainingMethod selected = (TrainingMethod) others.getSelectedItem();
				if (selected != null)
				{
					plugin.pinMethod(selected.id());
				}
			});
			detail.add(Box.createVerticalStrut(4));
			detail.add(text("Other methods at this level", DIM));
			detail.add(others);
		}
		detail.add(Box.createVerticalStrut(8));
		detail.add(text("Steps", TEXT));
		int index = snapshot.running() ? snapshot.stepIndex() : -1;
		int number = 1;
		for (GuideStep step : method.steps())
		{
			boolean current = number - 1 == index;
			String prefix = current ? ">> " : number + ". ";
			Color color = current ? new Color(255, 196, 90) : TEXT;
			if (step.instruction().contains("Wilderness") || step.instruction().contains("dangerous"))
			{
				color = current ? new Color(255, 140, 110) : WARN;
			}
			detail.add(text(prefix + step.instruction(), color));
			number++;
		}
		if (method.loopFrom() > 0)
		{
			detail.add(text("After the last step, repeat from step " + (method.loopFrom() + 1) + ".", DIM));
		}
		else if (method.steps().size() > 1)
		{
			detail.add(text("These steps repeat.", DIM));
		}
		if (!method.optimizations().isEmpty())
		{
			detail.add(Box.createVerticalStrut(8));
			detail.add(text("Optimizations", TEXT));
			for (String optimization : method.optimizations())
			{
				detail.add(text("- " + optimization, DIM));
			}
		}
		if (method.wikiTitle() != null)
		{
			JButton wiki = button("Open wiki");
			wiki.addActionListener(event -> plugin.openWiki(method.wikiTitle()));
			detail.add(Box.createVerticalStrut(4));
			detail.add(wiki);
		}
		appendLockedRoutes(snapshot);
		refresh();
	}

	private void appendLockedRoutes(GuideSnapshot snapshot)
	{
		if (snapshot.lockedRoutes().isEmpty())
		{
			return;
		}
		detail.add(Box.createVerticalStrut(6));
		detail.add(text("Locked routes", DIM));
		for (String locked : snapshot.lockedRoutes())
		{
			detail.add(text(locked, DIM));
		}
	}

	private String stats(GuideSnapshot snapshot)
	{
		TrainingMethod method = snapshot.method();
		int xpToLevel = TrainingMath.xpBetween(snapshot.xp(), snapshot.level() + 1);
		int xpToGoal = TrainingMath.xpBetween(snapshot.xp(), snapshot.goal());
		StringBuilder text = new StringBuilder();
		if (snapshot.loggedIn())
		{
			text.append("Level ").append(snapshot.level())
				.append(" · ").append(TrainingMath.xp(snapshot.xp())).append(" XP\n")
				.append(TrainingMath.xp(xpToLevel)).append(" XP to level ").append(Math.min(99, snapshot.level() + 1)).append("\n")
				.append(TrainingMath.xp(xpToGoal)).append(" XP to goal ").append(snapshot.goal());
		}
		else
		{
			text.append("Goal ").append(snapshot.goal());
		}
		text.append("\nTypical ").append(TrainingMath.rate(method.xpPerHour()));
		if (method.xpEach() > 0 && xpToGoal > 0)
		{
			int actions = TrainingMath.actions(xpToGoal, method.xpEach());
			text.append("\nAbout ").append(String.format("%,d", actions)).append(" actions to the goal");
		}
		if (xpToGoal > 0)
		{
			text.append("\nAbout ").append(TrainingMath.duration(TrainingMath.millis(xpToGoal, method.xpPerHour()))).append(" at the typical rate");
		}
		if (snapshot.running() && !snapshot.distanceText().isEmpty())
		{
			text.append("\n").append(snapshot.distanceText());
		}
		if (snapshot.running())
		{
			text.append("\nSession ").append(TrainingMath.xp(snapshot.sessionXp())).append(" XP · ").append(TrainingMath.rate(snapshot.sessionPerHour()));
			if (snapshot.sessionPerHour() > 0 && xpToGoal > 0)
			{
				text.append("\nAbout ").append(TrainingMath.duration(TrainingMath.millis(xpToGoal, snapshot.sessionPerHour()))).append(" at your session rate");
			}
		}
		return text.toString();
	}

	private void styleSkills()
	{
		skills.setBackground(ColorScheme.DARK_GRAY_COLOR);
		skills.setAlignmentX(Component.LEFT_ALIGNMENT);
		for (Skill skill : Skill.values())
		{
			if ("Overall".equals(skill.getName()))
			{
				continue;
			}
			JToggleButton button = new JToggleButton(skill.getName());
			button.setMargin(new Insets(1, 2, 1, 2));
			button.setFocusable(false);
			button.setBackground(ColorScheme.DARKER_GRAY_COLOR);
			button.setForeground(TEXT);
			skillGroup.add(button);
			skillButtons.put(skill, button);
			button.addActionListener(event ->
			{
				if (!suppress && button.isSelected())
				{
					plugin.setSkill(skill);
				}
			});
			skills.add(button);
		}
	}

	private JPanel labeled(String name, Component field)
	{
		JPanel row = new JPanel(new BorderLayout(6, 0));
		row.setBackground(ColorScheme.DARK_GRAY_COLOR);
		row.setAlignmentX(Component.LEFT_ALIGNMENT);
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 28));
		JLabel label = new JLabel(name);
		label.setForeground(DIM);
		row.add(label, BorderLayout.WEST);
		row.add(field, BorderLayout.CENTER);
		return row;
	}

	private JPanel column()
	{
		JPanel panel = new JPanel();
		panel.setLayout(new BoxLayout(panel, BoxLayout.Y_AXIS));
		panel.setBackground(ColorScheme.DARK_GRAY_COLOR);
		panel.setAlignmentX(Component.LEFT_ALIGNMENT);
		return panel;
	}

	private JPanel controls(GuideSnapshot snapshot)
	{
		JPanel box = column();
		JButton start = button(snapshot.running() ? "Stop guiding" : "Start guiding");
		start.addActionListener(event ->
		{
			if (snapshot.running())
			{
				plugin.stopGuide();
			}
			else
			{
				plugin.startGuide();
			}
		});
		box.add(start);
		if (snapshot.running())
		{
			JPanel row = new JPanel(new GridLayout(1, 3, 4, 0));
			row.setBackground(ColorScheme.DARK_GRAY_COLOR);
			row.setAlignmentX(Component.LEFT_ALIGNMENT);
			row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 26));
			JButton back = button("Back");
			JButton next = button("Next");
			JButton bank = button("Bank");
			back.addActionListener(event -> plugin.previousStep());
			next.addActionListener(event -> plugin.nextStep());
			bank.addActionListener(event -> plugin.bankStep());
			row.add(back);
			row.add(next);
			row.add(bank);
			box.add(Box.createVerticalStrut(4));
			box.add(row);
		}
		return box;
	}

	private WrapLabel text(String value, Color color)
	{
		WrapLabel label = new WrapLabel(html(value), color);
		label.setAlignmentX(Component.LEFT_ALIGNMENT);
		return label;
	}

	private JButton button(String value)
	{
		JButton button = new JButton(value);
		button.setFocusable(false);
		button.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		button.setForeground(TEXT);
		button.setAlignmentX(Component.LEFT_ALIGNMENT);
		button.setMaximumSize(new Dimension(Integer.MAX_VALUE, 28));
		return button;
	}

	private static String html(String value)
	{
		return "<html><body>" + escape(value) + "</body></html>";
	}

	private static final class WrapLabel extends JLabel
	{
		private WrapLabel(String html, Color color)
		{
			super(html);
			setForeground(color);
			putClientProperty(BasicHTML.propertyKey, null);
			setText(html);
		}

		@Override
		public Dimension getPreferredSize()
		{
			int width = 205;
			if (getParent() != null && getParent().getWidth() > 40)
			{
				Insets insets = getParent().getInsets();
				width = Math.max(1, getParent().getWidth() - insets.left - insets.right);
			}
			View view = (View) getClientProperty(BasicHTML.propertyKey);
			if (view == null)
			{
				return super.getPreferredSize();
			}
			Insets insets = getInsets();
			view.setSize(Math.max(1, width - insets.left - insets.right), 0);
			int height = (int) Math.ceil(view.getPreferredSpan(View.Y_AXIS));
			return new Dimension(width, Math.max(16, height + insets.top + insets.bottom));
		}

		@Override
		public Dimension getMinimumSize()
		{
			return new Dimension(0, getPreferredSize().height);
		}

		@Override
		public Dimension getMaximumSize()
		{
			Dimension preferred = getPreferredSize();
			return new Dimension(Integer.MAX_VALUE, preferred.height);
		}
	}

	private static String escape(String value)
	{
		return value
			.replace("&", "&amp;")
			.replace("<", "&lt;")
			.replace(">", "&gt;")
			.replace("\n", "<br>");
	}

	private void refresh()
	{
		revalidate();
		repaint();
	}
}

