package com.levelinghelper.guide;

import com.levelinghelper.model.AccountMode;
import com.levelinghelper.model.TrainingMethod;
import com.levelinghelper.model.TrainingStyle;
import java.util.ArrayList;
import java.util.List;
import net.runelite.api.Skill;

public final class MethodSelector
{
	private MethodSelector()
	{
	}

	public static TrainingMethod select(List<TrainingMethod> all, Skill skill, AccountMode mode, TrainingStyle style, int level, LevelLookup lookup)
	{
		List<TrainingMethod> pool = new ArrayList<TrainingMethod>();
		for (TrainingMethod method : all)
		{
			if (method.skill() != skill || !method.modes().contains(mode) || !method.containsLevel(level))
			{
				continue;
			}
			if (!method.requirementsMet(lookup))
			{
				continue;
			}
			pool.add(method);
		}
		TrainingMethod picked = best(pool, style);
		if (picked != null)
		{
			return picked;
		}
		for (TrainingStyle fallback : fallbacks(style))
		{
			picked = best(pool, fallback);
			if (picked != null)
			{
				return picked;
			}
		}
		return null;
	}

	public static List<TrainingMethod> alternatives(List<TrainingMethod> all, Skill skill, AccountMode mode, int level, LevelLookup lookup)
	{
		List<TrainingMethod> pool = new ArrayList<TrainingMethod>();
		for (TrainingMethod method : all)
		{
			if (method.skill() != skill || !method.modes().contains(mode) || !method.containsLevel(level))
			{
				continue;
			}
			if (!method.requirementsMet(lookup))
			{
				continue;
			}
			pool.add(method);
		}
		return pool;
	}

	private static TrainingMethod best(List<TrainingMethod> pool, TrainingStyle style)
	{
		TrainingMethod best = null;
		for (TrainingMethod method : pool)
		{
			if (!method.styles().contains(style))
			{
				continue;
			}
			if (best == null || better(method, best))
			{
				best = method;
			}
		}
		return best;
	}

	private static boolean better(TrainingMethod candidate, TrainingMethod current)
	{
		if (candidate.priority() != current.priority())
		{
			return candidate.priority() > current.priority();
		}
		if (candidate.minLevel() != current.minLevel())
		{
			return candidate.minLevel() > current.minLevel();
		}
		return candidate.xpPerHour() > current.xpPerHour();
	}

	private static TrainingStyle[] fallbacks(TrainingStyle style)
	{
		switch (style)
		{
			case FAST:
				return new TrainingStyle[]{TrainingStyle.BALANCED, TrainingStyle.AFK, TrainingStyle.PROFIT};
			case AFK:
				return new TrainingStyle[]{TrainingStyle.BALANCED, TrainingStyle.PROFIT, TrainingStyle.FAST};
			case PROFIT:
				return new TrainingStyle[]{TrainingStyle.BALANCED, TrainingStyle.AFK, TrainingStyle.FAST};
			case BALANCED:
			default:
				return new TrainingStyle[]{TrainingStyle.FAST, TrainingStyle.AFK, TrainingStyle.PROFIT};
		}
	}
}

package com.levelinghelper.guide;

import java.util.Locale;
import net.runelite.api.Experience;
import net.runelite.api.coords.WorldPoint;

public final class TrainingMath
{
	private TrainingMath()
	{
	}

	public static int xpBetween(int currentXp, int targetLevel)
	{
		int clamped = Math.max(1, Math.min(99, targetLevel));
		return Math.max(0, Experience.getXpForLevel(clamped) - Math.max(0, currentXp));
	}

	public static int actions(int xpRemaining, double xpEach)
	{
		if (xpRemaining <= 0)
		{
			return 0;
		}
		if (xpEach <= 0)
		{
			return -1;
		}
		return (int) Math.ceil(xpRemaining / xpEach);
	}

	public static long millis(int xpRemaining, double xpPerHour)
	{
		if (xpRemaining <= 0)
		{
			return 0L;
		}
		if (xpPerHour <= 0)
		{
			return -1L;
		}
		return (long) (xpRemaining / xpPerHour * 3_600_000.0);
	}

	public static String duration(long millis)
	{
		if (millis < 0)
		{
			return "n/a";
		}
		if (millis == 0)
		{
			return "done";
		}
		long minutes = millis / 60000L;
		if (minutes < 1)
		{
			return "under a minute";
		}
		if (minutes < 60)
		{
			return minutes + " min";
		}
		long hours = minutes / 60;
		long rem = minutes % 60;
		if (hours < 48)
		{
			return hours + "h " + rem + "m";
		}
		long days = hours / 24;
		return days + "d " + (hours % 24) + "h";
	}

	public static String xp(int value)
	{
		int abs = Math.abs(value);
		if (abs >= 1_000_000)
		{
			return String.format(Locale.US, "%.2fm", value / 1_000_000.0);
		}
		if (abs >= 10_000)
		{
			return String.format(Locale.US, "%.1fk", value / 1000.0);
		}
		return String.format(Locale.US, "%,d", value);
	}

	public static String rate(double perHour)
	{
		if (perHour <= 0)
		{
			return "n/a";
		}
		return xp((int) Math.round(perHour)) + "/hr";
	}

	public static int combatLevel(int attack, int strength, int defence, int hitpoints, int prayer, int ranged, int magic)
	{
		double base = 0.25 * (defence + hitpoints + (prayer / 2));
		double melee = 0.325 * (attack + strength);
		double range = 0.325 * ((ranged * 3) / 2);
		double mage = 0.325 * ((magic * 3) / 2);
		return (int) Math.floor(base + Math.max(melee, Math.max(range, mage)));
	}

	public static String direction(WorldPoint from, WorldPoint to)
	{
		if (from == null || to == null)
		{
			return "";
		}
		if (from.getPlane() != to.getPlane())
		{
			return "on another floor";
		}
		int dx = to.getX() - from.getX();
		int dy = to.getY() - from.getY();
		int dist = Math.max(Math.abs(dx), Math.abs(dy));
		if (dist == 0)
		{
			return "at the spot";
		}
		String northSouth = dy > 2 ? "north" : dy < -2 ? "south" : "";
		String eastWest = dx > 2 ? "east" : dx < -2 ? "west" : "";
		String compass = (northSouth + eastWest).isEmpty() ? "nearby" : northSouth + eastWest;
		return dist + " tiles " + compass;
	}
}

package com.levelinghelper.guide;

import java.util.function.LongSupplier;
import net.runelite.api.Skill;

public final class XpSession
{
	private Skill skill;
	private int startXp;
	private int lastXp;
	private int gained;
	private long startMs;
	private final LongSupplier clock;

	public XpSession()
	{
		this(() -> System.nanoTime() / 1_000_000L);
	}

	public XpSession(LongSupplier clock)
	{
		this.clock = clock;
	}

	public void start(Skill skill, int currentXp)
	{
		this.skill = skill;
		this.startXp = currentXp;
		this.lastXp = currentXp;
		this.gained = 0;
		this.startMs = clock.getAsLong();
	}

	public void stop()
	{
		skill = null;
		gained = 0;
		startXp = 0;
		lastXp = 0;
	}

	public boolean active()
	{
		return skill != null;
	}

	public Skill skill()
	{
		return skill;
	}

	public int gained()
	{
		return gained;
	}

	public void onXp(Skill changed, int xp)
	{
		if (skill == null || changed != skill)
		{
			return;
		}
		if (xp > lastXp)
		{
			gained += xp - lastXp;
			lastXp = xp;
		}
		else if (xp < lastXp)
		{
			// An account change or XP reset must never be counted as negative training.
			start(changed, xp);
		}
	}

	public double xpPerHour()
	{
		if (skill == null || gained <= 0)
		{
			return 0;
		}
		long elapsed = clock.getAsLong() - startMs;
		if (elapsed < 15_000L)
		{
			return 0;
		}
		return gained * 3_600_000.0 / elapsed;
	}

	public int startXp()
	{
		return startXp;
	}
}

