		EnumSet<TrainingStyle> styles,
		int minLevel,
		int maxLevel,
		int priority,
		int combatRequirement,
		List<SkillReq> requirements,
		double xpEach,
		int xpPerHour,
		String rateNote,
		String summary,
		String wikiTitle,
		List<String> optimizations,
		List<GuideStep> steps,
