public class CatalogRequirementsTest
{
	private static final class Profile implements LevelLookup
	{
		final EnumSet<Quest> quests = EnumSet.noneOf(Quest.class);
		boolean wilderness;
		public int level(Skill skill) { return 99; }
		public int combatLevel() { return 126; }
		public boolean questComplete(Quest quest) { return quests.contains(quest); }
		public boolean allowWilderness() { return wilderness; }
	}

	private TrainingMethod select(Skill skill, TrainingStyle style, int level, Profile profile)
	{
		return MethodSelector.select(TrainingCatalog.all(), skill, AccountMode.P2P, style, level, profile);
	}

	@Test
	public void questLockedMagicFallsBackAndIceBurstRequiresLevel70()
	{
		Profile profile = new Profile();
		assertEquals("Combat spells", select(Skill.MAGIC, TrainingStyle.FAST, 70, profile).name());
		profile.quests.add(Quest.DESERT_TREASURE_I);
		assertEquals("Combat spells", select(Skill.MAGIC, TrainingStyle.FAST, 69, profile).name());
		assertEquals("Ice Burst", select(Skill.MAGIC, TrainingStyle.FAST, 70, profile).name());
		TrainingMethod burst = select(Skill.MAGIC, TrainingStyle.FAST, 70, profile);
		ItemRequirement mask = burst.items().get(0);
		assertTrue(mask.equipped());
		assertTrue(mask.met(id -> id == ItemID.FACEMASK ? 1 : 0));
		assertTrue(mask.met(id -> id == ItemID.ARAXYTE_SLAYER_HELMET_I_29822 ? 1 : 0));
		assertFalse(mask.met(id -> id == ItemID.BLACK_MASK ? 1 : 0));
	}

	@Test
	public void wildernessNeedsExplicitOptInAcrossEveryAffectedSkill()
	{
		Profile profile = new Profile();
		for (Skill skill : new Skill[]{Skill.PRAYER, Skill.HUNTER, Skill.AGILITY})
		{
			TrainingMethod method = select(skill, TrainingStyle.FAST, 60, profile);
			assertNotNull(method);
			assertNotEquals(RouteRisk.WILDERNESS, method.risk());
		}
		profile.wilderness = true;
		assertEquals("Chaos altar", select(Skill.PRAYER, TrainingStyle.FAST, 60, profile).name());
		assertEquals("Wilderness course", select(Skill.AGILITY, TrainingStyle.FAST, 60, profile).name());
		assertEquals("Black chinchompas", select(Skill.HUNTER, TrainingStyle.FAST, 80, profile).name());
	}

	@Test
	public void resourceTargetsDistinguishOreTypesAndDepletedRocks()
	{
		GuideStep iron = select(Skill.MINING, TrainingStyle.FAST, 20, new Profile()).steps().get(2);
		assertTrue(iron.matchesObject(ObjectID.IRON_ROCKS, "Rocks"));
		assertFalse(iron.matchesObject(ObjectID.COPPER_ROCKS_11161, "Rocks"));
		assertFalse(iron.matchesObject(ObjectID.ROCKS_11390, "Rocks"));
		assertFalse(iron.matchesNpc(1, "Rocks"));
	}

	@Test
	public void anglerfishUseTheActualNpcAndBarbarianFishingRequiresBait()
	{
		Profile profile = new Profile();
		TrainingMethod angler = select(Skill.FISHING, TrainingStyle.PROFIT, 82, profile);
		assertEquals("Anglerfish", angler.name());
		assertTrue(angler.summary().contains("Port Piscarilius"));
		assertTrue(angler.steps().get(2).matchesNpc(6825, "Rod Fishing spot"));
		assertFalse(angler.steps().get(2).matchesNpc(1510, "Fishing spot"));
		TrainingMethod barb = select(Skill.FISHING, TrainingStyle.BALANCED, 48, profile);
		assertEquals("Barbarian fishing", barb.name());
		assertTrue(barb.items().stream().anyMatch(item -> item.met(id -> id == ItemID.FEATHER ? 100 : 0)));
	}

	@Test
	public void unlockedProfilesCoverAllStylesAndLevelsWithRealisticPrimaryLevels()
	{
		for (Skill skill : Skill.values())
		{
			if (skill == Skill.OVERALL) continue;
			for (int level = 1; level <= 99; level++)
			{
				final int primaryLevel = level;
				LevelLookup profile = new LevelLookup()
				{
					public int level(Skill queried) { return queried == skill ? primaryLevel : 99; }
					public int combatLevel() { return 126; }
					public boolean questComplete(Quest quest) { return true; }
				};
				for (TrainingStyle style : TrainingStyle.values())
				{
					TrainingMethod method = MethodSelector.select(TrainingCatalog.all(), skill, AccountMode.P2P, style, level, profile);
					// Quest rewards make some pre-unlock levels unattainable on an unlocked account.
					if (skill == Skill.HERBLORE && level < 3 || skill == Skill.SAILING && level < 2) continue;
					assertNotNull(skill + " " + style + " " + level, method);
					assertTrue(method.requirementsMet(profile));
				}
			}
		}
	}

	@Test
	public void targetNamesAreLocaleIndependentAndCatalogSetsCannotBeMutated()
	{
		Locale previous = Locale.getDefault();
		try
		{
			Locale.setDefault(Locale.forLanguageTag("tr-TR"));
			GuideStep step = GuideSteps.roam("Fish", AdvanceWhen.MANUAL, "FISHING SPOT");
			assertTrue(step.matchesNpc(1, "Fishing spot"));
		}
		finally { Locale.setDefault(previous); }
		TrainingMethod method = TrainingCatalog.all().get(0);
		method.modes().clear();
		assertFalse(method.modes().isEmpty());
	}
}

package com.levelinghelper;

import com.levelinghelper.guide.DirectionArrow;
import java.awt.Polygon;
import java.awt.Rectangle;
import org.junit.Test;
import static org.junit.Assert.*;

public class DirectionArrowTest
{
	private final Rectangle viewport = new Rectangle(20, 40, 800, 500);

	@Test
	public void arrowRotatesWithTheCameraInAllFourCardinalDirections()
	{
		Polygon north = DirectionArrow.polygon(0, 100, 0, viewport);
		Polygon east = DirectionArrow.polygon(0, 100, 4096, viewport);
		Polygon south = DirectionArrow.polygon(0, 100, 8192, viewport);
		Polygon west = DirectionArrow.polygon(0, 100, 12288, viewport);
		assertTrue(north.ypoints[0] < viewport.getCenterY());
		assertTrue(east.xpoints[0] > viewport.getCenterX());
		assertTrue(south.ypoints[0] > viewport.getCenterY());
		assertTrue(west.xpoints[0] < viewport.getCenterX());
		for (Polygon arrow : new Polygon[]{north, east, south, west})
		{
			for (int i = 0; i < arrow.npoints; i++) assertTrue(viewport.contains(arrow.xpoints[i], arrow.ypoints[i]));
		}
	}

	@Test
	public void degenerateAndSmallViewportsDoNotProduceOffscreenArrows()
	{
		assertNull(DirectionArrow.polygon(0, 0, 0, viewport));
		assertNull(DirectionArrow.polygon(1, 0, 0, new Rectangle(10, 10)));
		Rectangle small = new Rectangle(20, 30, 40, 40);
		Polygon arrow = DirectionArrow.polygon(-100, 100, 0, small);
		for (int i = 0; i < arrow.npoints; i++) assertTrue(small.contains(arrow.xpoints[i], arrow.ypoints[i]));
	}
}

package com.levelinghelper;

import com.levelinghelper.guide.*;
import com.levelinghelper.model.*;
import java.util.ArrayList;
import java.util.List;
import net.runelite.api.Skill;
import net.runelite.api.coords.WorldPoint;
import org.junit.Test;
import static org.junit.Assert.*;

public class GuideControllerRegressionTest
{
	private final WorldPoint at = new WorldPoint(100, 100, 0);

	private GuideController guide(GuideStep... steps)
	{
		List<TrainingMethod> methods = new ArrayList<>();
		TrainingMethod.Builder builder = TrainingMethod.builder(methods, Skill.MINING, "Regression")
			.summary("Exercise the route state machine");
		for (GuideStep step : steps) builder.step(step);
		builder.save();
		GuideController controller = new GuideController();
		controller.start(methods.get(0));
		return controller;
	}

	private GuideTick tick(boolean bank, boolean full, boolean gone, boolean prepared)
	{
		return new GuideTick(at, bank, full, gone, false, prepared);
	}

	@Test
	public void droppingBeforeTheFollowingTickDoesNotStall()
	{
		GuideController controller = guide(GuideSteps.train("Mine", at, AdvanceWhen.INVENTORY_FULL), GuideSteps.drop("Drop"));
		assertTrue(controller.tick(tick(false, true, false, true), true, 10));
		assertEquals(1, controller.stepIndex());
		assertTrue(controller.tick(tick(false, false, false, true), true, 10));
		assertEquals(0, controller.stepIndex());
	}

	@Test
	public void hopperRemembersFullInventoryWhenItIsEmptiedBeforeTheNextTick()
	{
		GuideController controller = guide(GuideSteps.train("Mine", at, AdvanceWhen.INVENTORY_FULL), GuideSteps.hopper("Deposit", at));
		controller.tick(tick(false, true, false, true), true, 10);
		assertTrue(controller.tick(tick(false, false, false, true), true, 10));
	}

	@Test
	public void bankRequiresAnObservedOpenAndTheRequiredSupplies()
	{
		GuideController controller = guide(GuideSteps.bank("Withdraw", at), GuideSteps.note("Ready"));
		assertFalse(controller.tick(tick(false, false, false, true), true, 10));
		assertFalse(controller.tick(tick(true, false, false, false), true, 10));
		assertFalse(controller.tick(tick(false, false, false, false), true, 10));
		assertTrue(controller.tick(tick(false, false, false, true), true, 10));
	}

	@Test
	public void missingMaterialsAreNotMistakenForACompletedInventory()
	{
		GuideController controller = guide(GuideSteps.untilEmpty("Process", at, "Grapes"), GuideSteps.note("Finished"));
		assertFalse(controller.tick(tick(false, false, true, true), true, 10));
		controller.observe(tick(false, false, false, true));
		assertTrue(controller.tick(tick(false, false, true, true), true, 10));
	}

	@Test
	public void manualPauseStillObservesBankStateAndBackClearsTheLatch()
	{
		GuideController controller = guide(GuideSteps.bank("Bank", at), GuideSteps.note("Ready"));
		assertFalse(controller.tick(tick(true, false, false, true), false, 10));
		assertTrue(controller.tick(tick(false, false, false, true), true, 10));
		controller.back();
		assertFalse(controller.tick(tick(false, false, false, true), true, 10));
	}

	@Test
	public void arrivalSettingCapsTheRouteRadiusAndHonorsThePlane()
	{
		GuideController controller = guide(GuideSteps.travel("Walk", at, 18), GuideSteps.note("Arrived"));
		assertFalse(controller.tick(new GuideTick(at.dx(8), false, false, false, false), true, 3));
		assertFalse(controller.tick(new GuideTick(at.dz(1), false, false, false, false), true, 3));
		assertTrue(controller.tick(new GuideTick(at.dx(2), false, false, false, false), true, 3));
	}

	@Test
	public void unavailableInventoryCannotArmMaterialCompletionOrFinishDropping()
	{
		GuideController controller = guide(GuideSteps.untilEmpty("Process", at, "Grapes"), GuideSteps.note("Finished"));
		assertFalse(controller.tick(new GuideTick(at, false, false, false, false, true, false), true, 10));
		assertFalse(controller.tick(tick(false, false, true, true), true, 10));
		controller = guide(GuideSteps.train("Mine", at, AdvanceWhen.INVENTORY_FULL), GuideSteps.drop("Drop"));
		controller.tick(tick(false, true, false, true), true, 10);
		assertFalse(controller.tick(new GuideTick(at, false, false, false, false, true, false), true, 10));
		assertTrue(controller.tick(tick(false, false, false, true), true, 10));
	}
}

