		session = new SessionLifecycle(client);
		set("client", client);
		set("clientThread", thread);
		set("config", config);
		set("configManager", mock(ConfigManager.class));
		set("itemManager", mock(ItemManager.class));
		set("worldMapPointManager", map);
		set("overlayManager", mock(OverlayManager.class));
		set("clientToolbar", mock(ClientToolbar.class));
		set("targets", new TargetHighlighter(client));
		set("hintArrows", new HintArrowController(client));
		set("session", session);
		set("enabled", true);
	}

	private void set(String name, Object value) throws Exception
	{
		Field field = LevelingHelperPlugin.class.getDeclaredField(name);
		field.setAccessible(true);
		field.set(plugin, value);
	}

	private void start()
	{
		plugin.startGuide();
		thread.drain();
		assertTrue(plugin.controller().running());
	}

	@Test
	public void unsupportedSkillClearsTheOldGuideAndMapImmediately()
	{
		start();
		plugin.onGameTick(new GameTick());
		verify(map).add(any());
		plugin.setSkill(Skill.SLAYER);
		thread.drain();
		assertFalse(plugin.controller().running());
		assertEquals(0, session.gained());
		verify(map).remove(any());
	}

	@Test
	public void returningFromAnUnsupportedSkillRequiresAnExplicitRestart()
	{
		start();
		plugin.setSkill(Skill.SLAYER);
		thread.drain();
		plugin.setSkill(Skill.WOODCUTTING);
		thread.drain();
		plugin.onGameTick(new GameTick());
		assertFalse(plugin.controller().running());
		start();
	}

	@Test
	public void startingAnUnsupportedSkillDoesNotArmAFutureSelection()
	{
		plugin.setSkill(Skill.SLAYER);
		plugin.startGuide();
		thread.drain();
		assertFalse(plugin.controller().running());
		plugin.setSkill(Skill.WOODCUTTING);
		thread.drain();
		plugin.onGameTick(new GameTick());
		assertFalse(plugin.controller().running());
	}

	@Test
	public void switchingAMembersSkillToFreeModeClearsTheRoute()
	{
		plugin.setAccountMode(AccountMode.P2P);
		plugin.setSkill(Skill.AGILITY);
		thread.drain();
		start();
		plugin.setAccountMode(AccountMode.F2P);
		thread.drain();
		assertFalse(plugin.controller().running());
		plugin.setAccountMode(AccountMode.P2P);
		thread.drain();
		plugin.onGameTick(new GameTick());
		assertFalse(plugin.controller().running());
	}

	@Test
	public void stopRemainsStoppedWhenChangingSettings()
	{
		start();
		plugin.stopGuide();
		plugin.setSkill(Skill.FISHING);
		plugin.setTrainingStyle(TrainingStyle.FAST);
		thread.drain();
		plugin.onGameTick(new GameTick());
		assertFalse(plugin.controller().running());
	}

	@Test
	public void reachedGoalStopsAndDoesNotAutoRestart()
	{
		start();
		when(client.getRealSkillLevel(Skill.WOODCUTTING)).thenReturn(99);
		plugin.onStatChanged(new StatChanged(Skill.WOODCUTTING, 13034431, 99, 99));
		assertFalse(plugin.controller().running());
		plugin.onGameTick(new GameTick());
		assertFalse(plugin.controller().running());
	}

	@Test
	public void shutdownInvalidatesAlreadyQueuedCommandsAndDefersClientCleanup() throws Exception
	{
		start();
		plugin.startGuide();
		clearInvocations(client);
		SwingUtilities.invokeAndWait(() -> plugin.shutDown());
		assertFalse(plugin.active());
		verifyNoInteractions(client);
		thread.drain();
		assertFalse(plugin.controller().running());
	}

	@Test
	public void uiCommandsDoNotReadOrMutateTheClientOnTheSwingThread() throws Exception
	{
		clearInvocations(client);
		SwingUtilities.invokeAndWait(() -> plugin.setAccountMode(AccountMode.P2P));
		verifyNoInteractions(client);
		thread.drain();
		assertFalse(plugin.controller().running());
	}

	@Test
	public void logoutStopsTheGuideAndRequiresAnExplicitRestart()
	{
		start();
		session.onXp(Skill.WOODCUTTING, 101400);
		assertTrue(session.gained() > 0);
		GameStateChanged event = new GameStateChanged();
		event.setGameState(GameState.LOGIN_SCREEN);
		when(client.getGameState()).thenReturn(GameState.LOGIN_SCREEN);
		plugin.onGameStateChanged(event);
		assertFalse(plugin.controller().running());
		assertEquals(0, session.gained());
		when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
		plugin.onGameTick(new GameTick());
		assertFalse(plugin.controller().running());
	}

	@Test
	public void unchangedTicksReuseTheWorldMapMarker()
	{
		start();
		plugin.onGameTick(new GameTick());
		plugin.onGameTick(new GameTick());
		verify(map, times(1)).add(any());
		verify(map, never()).remove(any());
	}

	@Test
	public void enablingThePluginDoesNotStartGuidingBeforeTheUserAsks() throws Exception
	{
		SwingUtilities.invokeAndWait(() -> plugin.startUp());
		thread.drain();
		plugin.onGameTick(new GameTick());
		assertFalse(plugin.controller().running());
		plugin.startGuide();
		thread.drain();
		assertTrue(plugin.controller().running());
		SwingUtilities.invokeAndWait(() -> plugin.shutDown());
		thread.drain();
		SwingUtilities.invokeAndWait(() -> { });
	}

	@Test
	public void disablingDirectionArrowsAlsoDisablesTheNativeArrow()
	{
		when(config.showHintArrow()).thenReturn(true);
		when(config.showArrow()).thenReturn(false);
		start();
		plugin.onGameTick(new GameTick());
		verify(client, never()).setHintArrow(any(net.runelite.api.coords.WorldPoint.class));
		verify(client, never()).setHintArrow(any(NPC.class));
	}

	@Test
	public void dustDevilHighlightsRequireProtectionToRemainEquipped()
	{
		TrainingMethod burst = TrainingCatalog.all().stream().filter(method -> method.name().equals("Ice Burst")).findFirst().get();
		plugin.controller().start(burst);
		plugin.controller().advance();
		plugin.controller().advance();
		NPC dustDevil = mock(NPC.class);
		when(dustDevil.getId()).thenReturn(NpcID.DUST_DEVIL_7249);
		net.runelite.api.coords.WorldPoint location = client.getLocalPlayer().getWorldLocation();
		when(dustDevil.getWorldLocation()).thenReturn(location);
		when(client.getNpcs()).thenReturn(java.util.Collections.singletonList(dustDevil));
		plugin.onGameTick(new GameTick());
		assertTrue(plugin.highlightedNpcs().isEmpty());
		ItemContainer equipment = mock(ItemContainer.class);
		when(equipment.count(ItemID.FACEMASK)).thenReturn(1);
		when(client.getItemContainer(net.runelite.api.gameval.InventoryID.WORN)).thenReturn(equipment);
		plugin.onGameTick(new GameTick());
		assertEquals(1, plugin.highlightedNpcs().size());
		when(client.getItemContainer(net.runelite.api.gameval.InventoryID.WORN)).thenReturn(null);
		plugin.onGameTick(new GameTick());
		assertTrue(plugin.highlightedNpcs().isEmpty());
	}
}

package com.levelinghelper;

import com.levelinghelper.guide.XpSession;
import java.util.concurrent.atomic.AtomicLong;
import net.runelite.api.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class SessionLifecycleTest
{
	@Test
	public void rateUsesElapsedMonotonicTimeAndStopClearsTheCounters()
	{
		AtomicLong clock = new AtomicLong();
		XpSession xp = new XpSession(clock::get);
		xp.start(Skill.MINING, 1000);
		xp.onXp(Skill.MINING, 1100);
		assertEquals(0, xp.xpPerHour(), 0);
		clock.set(60000);
		assertEquals(6000, xp.xpPerHour(), 0.01);
		xp.onXp(Skill.FISHING, 500000);
		assertEquals(100, xp.gained());
		xp.stop();
		assertEquals(0, xp.gained());
		assertEquals(0, xp.xpPerHour(), 0);
	}

	@Test
	public void xpResetRebasesInsteadOfIgnoringFutureGains()
	{
		XpSession xp = new XpSession();
		xp.start(Skill.MINING, 1000);
		xp.onXp(Skill.MINING, 100);
		xp.onXp(Skill.MINING, 125);
		assertEquals(25, xp.gained());
	}

	@Test
	public void accountChangesAndReconnectsStartFreshBaselines()
	{
		Client client = mock(Client.class);
		Player player = mock(Player.class);
		when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
		when(client.getLocalPlayer()).thenReturn(player);
		when(player.getName()).thenReturn("First account");
		when(client.getSkillExperience(Skill.MINING)).thenReturn(1000);
		SessionLifecycle session = new SessionLifecycle(client);
		session.sync(Skill.MINING);
		session.onXp(Skill.MINING, 1025);
		assertEquals(25, session.gained());
		when(player.getName()).thenReturn("Second account");
		when(client.getSkillExperience(Skill.MINING)).thenReturn(100000);
		session.onXp(Skill.MINING, 100000);
		assertEquals(0, session.gained());
		session.onXp(Skill.MINING, 100025);
		assertEquals(25, session.gained());
		session.stop();
		when(client.getGameState()).thenReturn(GameState.LOGIN_SCREEN);
		session.onXp(Skill.MINING, 200000);
		assertEquals(0, session.gained());
		when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
		when(client.getSkillExperience(Skill.MINING)).thenReturn(100);
		session.sync(Skill.MINING);
		session.onXp(Skill.MINING, 125);
		assertEquals(25, session.gained());
	}
}

package com.levelinghelper;

import com.levelinghelper.guide.GuideSteps;
import com.levelinghelper.model.AdvanceWhen;
import com.levelinghelper.model.GuideStep;
import java.util.Arrays;
import java.util.Collections;
import net.runelite.api.*;
import net.runelite.api.coords.WorldPoint;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class TargetHighlighterTest
{
	private final WorldPoint at = new WorldPoint(100, 100, 0);
	private Client client;
	private TargetHighlighter targets;

	@Before
	public void setUp()
	{
		client = mock(Client.class);
		when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
		when(client.getNpcs()).thenReturn(Collections.emptyList());
		targets = new TargetHighlighter(client);
	}

	@Test
	public void movingNpcsAreReevaluatedWithoutSpawnEvents()
	{
		NPC npc = mock(NPC.class);
		when(npc.getId()).thenReturn(6825);
		when(npc.getName()).thenReturn("Rod Fishing spot");
		when(npc.getWorldLocation()).thenReturn(at);
		when(client.getNpcs()).thenReturn(Collections.singletonList(npc));
		GuideStep step = GuideSteps.train("Fish", at, AdvanceWhen.MANUAL).npcIds(6825);
		targets.refresh(step, true);
		assertEquals(Collections.singletonList(npc), targets.npcs());
		when(npc.getWorldLocation()).thenReturn(at.dx(100));
		targets.refresh(step, false);
		assertFalse(targets.visible());
	}

	@Test
	public void objectIdsRejectOtherOresAndNullImpostors()
	{
		GuideStep step = GuideSteps.train("Mine", at, AdvanceWhen.MANUAL, "Rocks").objectIds(11364);
		targets.refresh(step, true);
		GameObject object = mock(GameObject.class);
		when(object.getId()).thenReturn(11364);
		when(object.getWorldLocation()).thenReturn(at);
		ObjectComposition composition = mock(ObjectComposition.class);
		when(client.getObjectDefinition(11364)).thenReturn(composition);
		when(composition.getId()).thenReturn(11364);
		when(composition.getName()).thenReturn("Rocks");
		targets.considerObject(object);
		targets.considerObject(object);
		assertEquals(1, targets.objects().size());
		targets.remove(object);
		when(composition.getImpostorIds()).thenReturn(new int[]{11364, -1});
		when(composition.getImpostor()).thenReturn(null);
		targets.considerObject(object);
		assertFalse(targets.visible());
	}

	@Test
	public void roamingTargetsStillHonorTheCurrentPlaneAndNpcIds()
	{
		NPC right = mock(NPC.class);
		NPC wrongFloor = mock(NPC.class);
		NPC wrongId = mock(NPC.class);
		when(right.getId()).thenReturn(6825);
		when(right.getWorldLocation()).thenReturn(at);
		when(wrongFloor.getId()).thenReturn(6825);
		when(wrongFloor.getWorldLocation()).thenReturn(at.dz(1));
		when(wrongId.getId()).thenReturn(1510);
		when(wrongId.getWorldLocation()).thenReturn(at);
		when(client.getNpcs()).thenReturn(Arrays.asList(right, wrongFloor, wrongId));
		targets.refresh(GuideSteps.roam("Fish", AdvanceWhen.MANUAL).npcIds(6825), true);
		assertEquals(Collections.singletonList(right), targets.npcs());
	}

	@Test
	public void rooftopTargetsCanBeAboveTheGroundLevelStartTile()
	{
		when(client.getPlane()).thenReturn(3);
		NPC target = mock(NPC.class);
		when(target.getId()).thenReturn(1);
		when(target.getName()).thenReturn("Obstacle");
		when(target.getWorldLocation()).thenReturn(at.dz(3));
		when(client.getNpcs()).thenReturn(Collections.singletonList(target));
		targets.refresh(GuideSteps.trainWide("Course", at, 45, AdvanceWhen.MANUAL, "Obstacle").onAnyPlane(), true);
		assertTrue(targets.visible());
	}

	@Test
	public void stoppingClearsCachedTargetsAndIgnoresLaterSpawnEvents()
	{
		targets.refresh(GuideSteps.roam("Find", AdvanceWhen.MANUAL, "Cow"), true);
		targets.clear();
		NPC npc = mock(NPC.class);
		when(npc.getName()).thenReturn("Cow");
		when(npc.getWorldLocation()).thenReturn(at);
		targets.considerNpc(npc);
		assertFalse(targets.visible());
	}
}
